import common as c
from common import R,np
c.check();assert c.read(R/'validation.json')['passed'];z=c.load(R/'OOF.npz');assert c.sha(R/'OOF.npz')==c.read(R/'validation.json')['OOF_SHA256'];y=z['y'];fold=z['fold'];comparisons={};boots={}
with c.Monitor('score',300):
 draws=np.random.default_rng(202610207).integers(0,400,size=(10000,400));counts=np.stack([np.bincount(row,minlength=400) for row in draws])
 for label,old,new in [('standalone','uniform','tail_ema'),('fixed_ensemble','fixed_uniform','fixed_tail_ema')]:
  ae=(y-z[old])**2;be=(y-z[new])**2;ar=float(np.sqrt(ae.mean()));br=float(np.sqrt(be.mean()));delta=ar-br;assert abs((np.linalg.norm(y-z[old])-np.linalg.norm(y-z[new]))/20-delta)<1e-12;b=np.sqrt(counts@ae/400)-np.sqrt(counts@be/400);direct=np.array([np.sqrt(ae[ix].mean())-np.sqrt(be[ix].mean()) for ix in draws[:23]]);assert abs(b[:23]-direct).max()<1e-12;boots[label]=b;order=np.argsort(ae-be,kind='stable');keep=order[:-5];fg=[float(np.sqrt(ae[fold==k].mean())-np.sqrt(be[fold==k].mean())) for k in range(5)]
  comparisons[label]={'control_RMSE':ar,'candidate_RMSE':br,'gain':delta,'fold_gains':fg,'positive_folds':sum(x>0 for x in fg),'conditional_CI95':np.quantile(b,[.025,.975]).tolist(),'top5_removed_gain':float(np.sqrt(ae[keep].mean())-np.sqrt(be[keep].mean())),'top5_IDs':z['ids'][order[-5:]].tolist(),'positive_ID_count':int(np.sum(ae>be)),'prediction_delta_RMS':float(np.sqrt(np.mean((z[new]-z[old])**2)))}
 q=comparisons['standalone'];criteria={'technical_validation':True,'gain_at_least_0_02':q['gain']>=.02,'at_least3_folds':q['positive_folds']>=3,'CI_lower_positive':q['conditional_CI95'][0]>0,'top5_removed_positive':q['top5_removed_gain']>0};eligible=all(criteria.values());c.arrays(R/'bootstrap.npz',draws=draws,**boots)
 report={'study':207,'status':'저장 checkpoint 대조 완료. 추가 학습 없음.','policy':'epoch76–80만 사용한 beta0.5/epoch 정규화 지수 평균; 가중치1:2:4:8:16. 전체 update EMA가 아님.','comparisons':comparisons,'criteria':criteria,'further_review_eligible':eligible,'decision':'사전 기준 미달. 이 고정 후반 지수 평균 정책을 종료하고 기존 평균 및 best021 유지.' if not eligible else '사전 기준 충족 여부만 보고하고 정지. 추가 정책 탐색 또는 best021 교체 없음.','new_training':0,'optimizer_steps':0,'individual_epoch_scores':0,'policy_variants_scored':1,'best021_replaced':False,'CI_definition':'기준 RMSE - 후보 RMSE. 400개 ID paired bootstrap10000회, seed202610207. 기존 학습 결과에 조건부.','limitations':['같은 개발 400장의 누적 재사용과 선택 편향을 보정하지 않는다.','한 seed의 동일 학습 경로 대조이며 seed 분산을 추정하지 않는다.','이 유한 구간의 평균 대조는 매 update EMA나 전체 학습 EMA를 평가하지 않는다.','고정 앙상블은 기존 첫 seed 출력 치환 진단이며 후단 재학습이 아니다.','실패는 이 beta와 후반 5개 checkpoint 정책에 한정한다. 다른 decay 또는 구간을 탐색하지 않는다.'],'OOF_SHA256':c.sha(R/'OOF.npz'),'bootstrap_SHA256':c.sha(R/'bootstrap.npz'),'validation_SHA256':c.sha(R/'validation.json'),'plan_SHA256':c.sha(R/'plan.json'),'cost':0,'install_download_holdout_test_newCSV_submission':False};c.write(R/'summary.json',report);c.emit(report)
c.check()
